    public static int PiInfo(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells @out, emon.Port.Cells im, int sh, int objnum) {
