        // or the end after), or -1.
        int p = from;
        while ((p + 1) < end) {
            if ((emon.Port.CellsAt(cs, p) == 69) && ((emon.Port.CellsAt(cs, p + 1) == 73) && (((p == 0) || (PiWs(emon.Port.CellsAt(cs, p - 1)) == 1)) && (((p + 2) >= end) || (PiWs(emon.Port.CellsAt(cs, p + 2)) == 1))))) {
                return p;
            }
            p += 1;
        }
        return -1;
    }
    public static int PiInfoInline(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells @out, emon.Port.Cells im, emon.Port.Cells cs, int from, int end) {
