        // payload `Buf` and a transcript, which holds only the record, keys on what the bytes were. `tmp` and `words`
        // (16 cells) are scratch. Answers 0, or 1 when the image has no image codec.
        int codec = emon.Port.CellsAt(im, PiCodec);
        int where = input;
        int off = 0;
        int ln = 0;
        int gwhere = -1;
        int goff = 0;
        int gln = 0;
        int comps = 0;
        int i = 0;
        if (codec == 0) {
            return 1;
        }
        emon.Port.CellsDrop(words, 0);
        while (i < 16) {
            emon.Port.CellsPush(words, 0);
            i += 1;
        }
        if (emon.Port.CellsAt(im, PiOwn) == 1) {
            off = emon.Port.CellsAt(im, PiSstart);
            ln = emon.Port.CellsAt(im, PiSlen);
        } else {
            where = -2;
            off = emon.Port.BufLen(payload);
            ln = emon.Port.CellsLen(data);
            i = 0;
            while (i < ln) {
                emon.Port.BufPush(payload, emon.Port.CellsAt(data, i));
                i += 1;
            }
            PiShaWords(data, tmp, words, 0);
        }
        if (emon.Port.CellsLen(globals) > 0) {
            gwhere = -2;
            goff = emon.Port.BufLen(payload);
            gln = emon.Port.CellsLen(globals);
            i = 0;
            while (i < gln) {
                emon.Port.BufPush(payload, emon.Port.CellsAt(globals, i));
                i += 1;
            }
            PiShaWords(globals, tmp, words, 8);
        }
        if ((codec == 7) || (codec == 9)) {
            comps = emon.Port.CellsAt(im, PiNcomp);
        }
        Plan.RqDecodeImg(rq, id, PiFlt(codec), emon.Port.CellsAt(im, PiW), emon.Port.CellsAt(im, PiH), comps, emon.Port.CellsAt(im, PiBpc), emon.Port.CellsAt(im, PiK), emon.Port.CellsAt(im, PiCols), emon.Port.CellsAt(im, PiRows), emon.Port.CellsAt(im, PiCflags), where, off, ln, words, 0, gwhere, goff, gln, 8);
        return 0;
    }
}
